from typing import Optional

import attr
from taf.config.testline import TestLine  # type: ignore

from taf.ul.ue.sim.env_setup.devices.bts import BTS
from taf.ul.ue.sim.env_setup.ute_config_loader import get_ute_tl_config


@attr.s(cmp=False, hash=True)
class ENB(BTS):
    def _get_vlan_id(self) -> Optional[int]:
        # todo: fix getting vlan_id in case of eNB after changes to TestLine are done.
        tl_conf, _ = get_ute_tl_config()
        try:
            if isinstance(tl_conf, TestLine):
                for gnb in tl_conf.gnbs:
                    return gnb.cu.s1u.vlan_id
        except Exception:
            return None
        return None

    def _get_lmp_ip_for_taf(self):
        try:
            return self.configuration.airscale.common_units[0].lmp_connection.addr
        except AttributeError:
            return self.configuration.system_module.common_units[0].lmp_connection.addr

    def _get_taf_pdu_config(self):
        try:
            pdu_port = self.configuration.airscale.common_units[0].pdu_port
        except AttributeError:
            pdu_port = self.configuration.system_module.common_units[0].pdu_port
        return pdu_port

    def _get_lmp_password(self) -> str:
        try:
            return self.configuration.airscale.common_units[0].lmp_connection.password
        except AttributeError:
            return self.configuration.system_module.common_units[0].lmp_connection.password
